static void selection_click_key(SceneEditor* editor,size_t channel,int64_t frame,bool add) {
    SDL_Rect row;assert(SceneEditorTimelineTrackRect(channel,&row));
    SDL_SetModState(add?KMOD_SHIFT:KMOD_NONE);
    click(editor,(SDL_Rect){SceneEditorTimelineFrameX(frame),row.y+row.h/2,1,1});
    SDL_SetModState(KMOD_NONE);
}
