    assert(camera!=SIZE_MAX);SDL_Rect row;assert(SceneEditorTimelineTrackRect(camera,&row));click(editor,row);
    authoring_control(editor,"frame");authoring_text(editor,"20");authoring_control(editor,"value");authoring_text(editor,"0.2");
    authoring_control(editor,"frame");authoring_text(editor,"40");authoring_control(editor,"value");authoring_text(editor,"0.4");
    authoring_control(editor,"frame");authoring_text(editor,"100");
