    selection_click_key(editor,camera,40,true);
    assert(SceneEditorTimelineSelectionRead(&keys) && keys.count==2);
    assert(SceneEditorTimelineTrackRect(camera,&row));rev=SceneEditorDocumentRevision();
    dock_drag(editor,SceneEditorTimelineFrameX(24),row.y+row.h/2,SceneEditorTimelineFrameX(28),row.y+row.h/2,true);
    assert(SceneEditorDocumentRevision()==rev && SceneEditorTimelineSelectionRead(&keys) && keys.count==2);
