    assert(SceneEditorDocumentRevision()==rev+1 && SceneEditorTimelineKeySelected(doc.tracks[camera].track_id,28) && SceneEditorTimelineKeySelected(doc.tracks[camera].track_id,44));
    assert(SceneEditorTimelineCurrentSample(&sample) && sample.absolute_frame==100);
