    rev=SceneEditorDocumentRevision();authoring_control(editor,"duplicate_keys");assert(SceneEditorDocumentRevision()==rev);
    authoring_control(editor,"frame");authoring_text(editor,"120");authoring_control(editor,"duplicate_keys");
    assert(SceneEditorDocumentRevision()==rev+1 && SceneEditorTimelineKeySelected(doc.tracks[camera].track_id,120) && SceneEditorTimelineKeySelected(doc.tracks[camera].track_id,136));
