    selection_click_key(editor,camera,120,false);selection_click_key(editor,camera,136,true);rev=SceneEditorDocumentRevision();
    authoring_control(editor,"delete_keys");assert(SceneEditorDocumentRevision()==rev+1 && SceneEditorDocumentGetTimeline(&doc)==TIMELINE_STATUS_OK && doc.tracks[camera].key_count==6);
    choose_menu(editor,1,0);assert(SceneEditorDocumentGetTimeline(&doc)==TIMELINE_STATUS_OK && doc.tracks[camera].key_count==8);
    selection_click_key(editor,camera,120,false);authoring_control(editor,"next_key");
    assert(SceneEditorTimelineSelectionRead(&keys) && keys.primary.frame==136 && SceneEditorTimelineCurrentSample(&sample) && sample.absolute_frame==136);
    authoring_control(editor,"previous_key");assert(SceneEditorTimelineSelectionRead(&keys) && keys.primary.frame==120);
    authoring_control(editor,"frame");authoring_text(editor,"180");
    assert(SceneEditorTimelineSelectionRead(&keys) && keys.primary.frame==120 && SceneEditorTimelineCurrentSample(&sample) && sample.absolute_frame==180);
    capture(editor,"selection_independent.ppm");
