    capture(editor,"selection_compact.ppm");
    fprintf(stderr,"Timeline selection UI PASS: independent scrub/selection, selected inspector time/value, Shift selection, atomic group drag/cancel, copy/paste/duplicate/collision, group delete/undo/redo, next/previous keys, save/reopen, compact inspector\n");
